//! The two scales a new clip can be placed at — Fit and Fill — and nothing
//! else.
//!
//! Cut out of `edit_clip.rs` under the size rule, a pure move (road map
//! "audio" AP9's toll, `designs/adr/core-file-history.md`): `edit_clip.rs`
//! decides where a clip sits, and these two decide how big a new one is
//! drawn. Fit is a RESCUE for oversized footage and honours
//! `canvas.fit_new_clips`; Fill is a REQUIREMENT, ignores it, scales up as
//! readily as down and clamps to `SCALE_MAX`.

use crate::model::Project;
use crate::props_check::{SCALE_MAX, SCALE_MIN};

impl Project {
    /// Fit scale for a new clip: `min(cw/sw, ch/sh)` when `fit_new_clips`
    /// is on and the source exceeds the canvas, else 1 (spec §5.3). A
    /// source that already fits is never scaled UP — Fit is a rescue for
    /// oversized footage, not a stretch.
    pub(crate) fn fit_scale(&self, source_width: f64, source_height: f64) -> f64 {
        if !(self.canvas.fit_new_clips && source_width > 0.0 && source_height > 0.0) {
            return 1.0;
        }
        let canvas_width = f64::from(self.canvas.width);
        let canvas_height = f64::from(self.canvas.height);
        if source_width <= canvas_width && source_height <= canvas_height {
            return 1.0;
        }
        let scale = (canvas_width / source_width).min(canvas_height / source_height);
        if scale.is_finite() {
            scale.clamp(SCALE_MIN, SCALE_MAX)
        } else {
            1.0
        }
    }

    /// Fill scale: `max(cw/sw, ch/sh)`, the smallest scale that leaves no
    /// canvas showing — [`Project::fit_scale`]'s sibling, and what
    /// `edit_background.rs` gives a backdrop.
    ///
    /// Three differences from Fit, all of them one difference read three
    /// ways: Fit is a RESCUE for oversized footage and Fill is a
    /// REQUIREMENT. So it ignores `canvas.fit_new_clips` — a backdrop that
    /// leaves a bar down the side has failed at its one job whatever that
    /// flag says; it scales UP as readily as down, a source smaller than the
    /// canvas being exactly the case that needs it; and it clamps HERE, so
    /// no caller can store a scale `check_video` would refuse. The clamp's
    /// visible cost is `edit_zoom.rs`'s, for the same constant: on a
    /// 1920-wide canvas a source under 192 pixels cannot reach the edge, and
    /// what comes back is the biggest legal magnification rather than a
    /// refusal. A degenerate source has no ratio to take and answers 1;
    /// callers refuse one by name before they ever reach this.
    pub(crate) fn fill_scale(&self, source_width: f64, source_height: f64) -> f64 {
        let scale = (f64::from(self.canvas.width) / source_width)
            .max(f64::from(self.canvas.height) / source_height);
        if scale.is_finite() && scale > 0.0 {
            scale.clamp(SCALE_MIN, SCALE_MAX)
        } else {
            1.0
        }
    }
}
//! The document's canvas — spec §6, the `set_canvas` row.
//!
//! One op and the three things it has to do to the rest of the document
//! when it lands: check a dimension, rescale every clip's placement when
//! the size changes, and re-snap every stored time when the rate does.
//! `edit_track.rs` owns the track stack, the markers and the media list;
//! this file was cut out of it under the size rule and is the canvas half
//! of the same concern — the document's own shape rather than what sits
//! on it.
//!
//! The two rules worth knowing before reading:
//!
//! 1. **A canvas dimension is even**, because H.264 and HEVC encode in
//!    macroblocks over a chroma-subsampled plane. Catching it here makes
//!    it a message about the field the user just typed.
//! 2. **A rate change normalizes stored picture times**, so it re-snaps
//!    top-level and nested clips and top-level markers to the new grid — and a
//!    coarser grid can land two markers on one tick, which markers may
//!    never share.

use crate::model::{CanvasBlending, CanvasOutput, Color, Project};
use crate::outcome::Outcome;
use crate::props_check::{color_ok, SCALE_MAX, SCALE_MIN};
use crate::time::{self, Fps, Ticks};

/// Canvas dimension bounds. The floor is small enough for a thumbnail-sized
/// document and large enough that the compositor has pixels to work with;
/// the ceiling is past 8K, where a single frame is already 130 MB.
///
/// `pub(crate)` because `op_table.rs` publishes this range as `width`'s and
/// `height`'s bound: the published bound is SOURCED from the constant the
/// refusal below is written against, never retyped beside it.
pub(crate) const CANVAS_MIN: u32 = 16;
pub(crate) const CANVAS_MAX: u32 = 16384;

// ---- helpers -------------------------------------------------------------

/// A canvas dimension: inside the bounds AND even.
///
/// Even is not fussiness: H.264 and HEVC encode in macroblocks over a
/// chroma-subsampled plane, so an odd width or height is either refused by
/// the encoder or silently padded. Catching it here makes it a message
/// about the canvas field the user just typed instead of an export that
/// fails an hour later.
fn check_dimension(key: &str, value: u32) -> Result<(), String> {
    if !(CANVAS_MIN..=CANVAS_MAX).contains(&value) {
        return Err(format!(
            "{key} must be between {CANVAS_MIN} and {CANVAS_MAX}, not {value}"
        ));
    }
    if !value.is_multiple_of(2) {
        return Err(format!(
            "{key} must be even (h.264 encodes in macroblocks), not {value}"
        ));
    }
    Ok(())
}

/// Multiplies every clip's placement by the canvas size ratio, so a layout
/// built for one canvas lands in the same relative place on the next (spec
/// §6, `rescale_clips`).
///
/// `x` and `y` are per-axis offsets in canvas pixels, so each follows its
/// OWN axis ratio — that is what keeps a layer's distance from an edge
/// proportional when the aspect ratio changes too. `scale` is one uniform
/// factor and cannot follow two ratios, so it follows the SMALLER of them:
/// the same `min` Fit uses, which means a layer that fitted the old canvas
/// still fits the new one, where the larger ratio could push it off an
/// edge.
///
/// Action `end` patches are deliberately NOT rescaled: a patch is opaque
/// JSON (`actions.rs` interprets it), and the op is defined on the clip's
/// props. An animated move on a resized canvas therefore keeps its old
/// target, which is visible and fixable, unlike a patch this function
/// half-understood and rewrote.
fn rescale(project: &mut Project, old_width: u32, old_height: u32) {
    if old_width == 0 || old_height == 0 {
        return;
    }
    let width_ratio = f64::from(project.canvas.width) / f64::from(old_width);
    let height_ratio = f64::from(project.canvas.height) / f64::from(old_height);
    if !(width_ratio.is_finite() && height_ratio.is_finite()) {
        return;
    }
    let scale_ratio = width_ratio.min(height_ratio);
    for clip in project.clips.iter_mut() {
        if let Some(video) = clip.video.as_mut() {
            video.x *= width_ratio;
            video.y *= height_ratio;
            // Clamped to the same range `set_video` accepts, so a chain of
            // shrinks cannot leave a scale the inspector refuses to show.
            video.scale = (video.scale * scale_ratio).clamp(SCALE_MIN, SCALE_MAX);
        }
    }
}

/// Re-snaps stored picture times to the canvas's CURRENT frame grid, after
/// that grid has changed.
///
/// Yesterday's grid is not today's: a 24 fps boundary is not a 30 fps
/// boundary, so top-level and stored-nest clips, their action and present
/// base motion/text times, and top-level markers move to the new grid.
///
/// Three clamps keep the result valid: a media clip's duration is held to
/// the source it still has, snapped DOWN to the new grid, so a coarser rate
/// cannot round a whole-file clip past the end of its file (spec §11); a
/// duration that would round to zero becomes one frame (a zero-length clip
/// is what `validate` rejects), which is the ONE case the source bound
/// cannot hold and `evaluate.rs`'s clamp covers; and an action is kept
/// inside its clip — but a ramped clip's speed action, which is snapped and
/// left running past the end, the duration held again (spec §11 SR-19 (g)).
fn resnap(project: &mut Project) {
    let fps = project.canvas.fps;
    // Temporarily own each list so source/media lookup can borrow the whole
    // project while a clip is normalized. Visit each stored nest exactly
    // once, including orphans and nests shown by more than one clip.
    let mut clips = std::mem::take(&mut project.clips);
    for clip in &mut clips {
        project.resnap_clip_times(clip);
    }
    project.clips = clips;
    for index in 0..project.nests.len() {
        let mut clips = std::mem::take(&mut project.nests[index].clips);
        for clip in &mut clips {
            project.resnap_clip_times(clip);
        }
        project.nests[index].clips = clips;
    }
    for marker in project.markers.iter_mut() {
        marker.time = time::snap_to_frame(marker.time, fps).max(0);
    }
    // A coarser grid can land two markers on one tick, which markers may
    // never share. The alternative — refusing a document-wide rate change
    // because two marks are 3 ms apart — is far worse than dropping the
    // second of them, so the first in the list keeps the tick.
    //
    // A linear scan over a `Vec` rather than a set: markers are capped at
    // 1024 and this runs only on a rate change.
    let mut taken: Vec<Ticks> = Vec::with_capacity(project.markers.len());
    project.markers.retain(|marker| {

    project.markers.retain(|marker| {
        if taken.contains(&marker.time) {
            false
        } else {
            taken.push(marker.time);
            true
        }
    });
}

// ---- the op --------------------------------------------------------------

impl Project {
    /// Sets any subset of the document's canvas fields (spec §6). An
    /// omitted argument keeps its value.
    ///
    /// `rescale_clips` multiplies every clip's `x`, `y` and `scale` by the
    /// size ratio (see [`rescale`]) so a finished layout survives a resize.
    /// Changing `fps` re-snaps top-level and stored-nest clip times, present
    /// base motion/text timing, action spans and top-level markers.
    ///
    /// `Err` for a dimension outside 16..16384 or odd (H.264 needs even
    /// dimensions), a frame rate with a zero term, or a background channel
    /// outside 0..1.
    ///
    /// `output` sets the project's dynamic range (spec §11 HD-2, HD-13):
    /// `sdr` or `hlg`. It changes no clip and no grade — a grade's numbers
    /// keep their 0…1 meaning — and setting the output the canvas already
    /// has is an identity, like every other unchanged field, through
    /// `finish`.
    ///
    /// `blending` sets how layers blend (spec §11 GR-18, HD-16): `encoded`
    /// or `linear` light. It changes no clip and no grade, and the blending
    /// the canvas already has is an identity through `finish`, as `output`.
    ///
    /// The rate change is deliberately NOT re-checked against the overlap
    /// rule: re-snapping moves each edge by less than one frame, so an
    /// overlap can grow by at most a frame, and refusing a document-wide
    /// rate change over a one-frame drift would be worse than the drift.
    #[allow(clippy::too_many_arguments)]
    // The argument list IS the op's argument list (spec §6); a struct would
    // hold exactly the same nine optional fields and one more name.
    pub fn set_canvas(
        &self,
        width: Option<u32>,
        height: Option<u32>,
        fps: Option<Fps>,
        background: Option<Color>,
        rescale_clips: bool,
        fit_new_clips: Option<bool>,
        timecode_frames: Option<bool>,
        output: Option<CanvasOutput>,
        blending: Option<CanvasBlending>,
    ) -> Result<Outcome, String> {
        let width = match width {
            None => self.canvas.width,
            Some(given) => {
                check_dimension("canvas width", given)?;
                given
            }
        };
        let height = match height {
            None => self.canvas.height,
            Some(given) => {
                check_dimension("canvas height", given)?;
                given
            }
        };
        let fps = match fps {
            None => self.canvas.fps,
            Some(given) if given.is_valid() => given,
            Some(given) => {
                return Err(format!(
                    "canvas fps must be [num, den] with non-zero terms, not [{}, {}]",
                    given.num, given.den
                ))
            }
        };
        if let Some(background) = background.as_ref() {
            color_ok("canvas background", background)?;
        }

        let mut next = self.clone();
        next.canvas.width = width;
        next.canvas.height = height;
        next.canvas.fps = fps;
        if let Some(background) = background {
            next.canvas.background = background;
        }
        if let Some(fit_new_clips) = fit_new_clips {
            next.canvas.fit_new_clips = fit_new_clips;
        }
        if let Some(timecode_frames) = timecode_frames {
            next.canvas.timecode_frames = timecode_frames;
        }
        if let Some(output) = output {
            next.canvas.output = output;
        }
        if let Some(blending) = blending {
            next.canvas.blending = blending;
        }

        let resized = width != self.canvas.width || height != self.canvas.height;
        if rescale_clips && resized {
            rescale(&mut next, self.canvas.width, self.canvas.height);
        }
        if fps != self.canvas.fps {
            resnap(&mut next);
        }
        self.finish(next)
    }
}

//! The action ops — spec §6, table "Actions".
//!
//! An action is a span of CLIP time with an end patch: the clip's props
//! interpolate from whatever they are toward that patch across it (spec
//! §5.4). `actions.rs` evaluates them; this file is the four edits that put
//! one on a clip, retime it, change what it animates, and take it off
//! again.
//!
//! Split out of `edit_clip.rs` (which owns placement) because they are a
//! separate concern with one rule of their own — **actions on a clip may
//! not overlap**, and both `add_action` and `set_action` refuse rather than
//! repair, exactly as placement refuses rather than pushes. The lookups,
//! the frame snapping and [`Project::finish`] are `edit_clip.rs`'s
//! `pub(crate)` helpers, called and never restated.
//!
//! One asymmetry is deliberate and worth stating, and D1·2 moved where it
//! falls. An end patch is walked for keys and types like every other patch
//! ([`check_end_patch`], over `patch.rs`'s walk), so a misspelt key here is
//! refused by its path rather than stored and silently ignored; what stays
//! LENIENT is the VALUE, because the state a clip interpolates toward may
//! name something no stored group could hold, and because a half-written
//! animation must stay editable. The evaluator is the line of defence for
//! that — it clamps every value it produces (spec §5.4). The one exception
//! is a graphic prop's end (spec §11 G-34 (c)), checked against the op's
//! `schema`: nothing clamps a prop, and a curve between two in-range ends
//! stays in range. The forward
//! compatibility the old leniency was for lives in the FILE reader, which
//! keeps an `end` object exactly as it found it.
//!
//! It has exactly ONE refusal beyond "the patch must be an object", and it
//! is about a key that is not a value at all: `video.motion` (format
//! version 8) names a PRESET anchored to the clip's two ends, not a
//! quantity to ramp between two states, so an action cannot target it and
//! `set_action_end` says so by name. The refusal is a courtesy rather than
//! the enforcement — `evaluate_clip` restores the base motion over whatever
//! any end patch carries, which is what closes a hand-written file, a
//! pasted action and a project from another tool at once. A `graphic`
//! group in `patch` is `edit_action_graphic.rs`'s arm (spec §11 G-34); in
//! `off` it is an `Err`.

use serde_json::{json, Map, Value};

use crate::actions::{self, MAX_PATCH_DEPTH};
use crate::edit_action_graphic::{read_graphic_end, write_graphic_end, GRAPHIC_NOT_KEYED_OFF};
use crate::edit_action_speed::read_speed_end;
use crate::export::describe;
use crate::model::{Action, AudioProps, Curve, Project, ShapeProps, TextProps, VideoProps};
use crate::model_graphic::{check_count, check_schema};
use crate::outcome::Outcome;
use crate::patch::{check_group_patch, merge_group, unknown_key, Group};
use crate::speed_map::end_speed;
use crate::time::{Ticks, TIMESCALE};

/// Default duration for `add_action`: one second of animation, the length
/// the Actions table offers before the user drags either edge.
const DEFAULT_ACTION_DURATION: Ticks = TIMESCALE;

/// The action on the clip, other than `skip` (the one being edited), that
/// `[start, start+duration)` runs into — `None` when the span is free.
/// Actions on a clip may not overlap (spec §5.4); this is the question both
/// `add_action` and `set_action` refuse on, and it answers the offender
/// rather than a yes, because the refusal names it.
pub(crate) fn overlapping_action(
    actions: &[Action],
    skip: Option<u32>,
    start: Ticks,
    duration: Ticks,
) -> Option<&Action> {
    let end = start.saturating_add(duration);
    actions
        .iter()
        .filter(|a| Some(a.id) != skip)
        .find(|a| start < a.start.saturating_add(a.duration) && a.start < end)
}

/// The two action refusals, written once because `add_action` and
/// `set_action` ask exactly the same two questions of the same numbers
/// (deepening D2·3). Each names the span the caller asked for and the span
/// in its way, which is the pair of numbers a caller needs to pick another
/// one without asking the project again.
pub(crate) fn action_overlaps(clip: u32, other: &Action) -> String {
    format!(
        "action {} on clip {clip} already runs from {} to {} ticks, and two actions on one \
         clip may not overlap",
        other.id,
        other.start,
        other.start.saturating_add(other.duration)
    )
}

pub(crate) fn action_past_end(clip: u32, start: Ticks, duration: Ticks, length: Ticks) -> String {
    format!(
        "an action of {duration} ticks at {start} would end at {}, past clip {clip}'s own \
         end at {length} ticks",
        start.saturating_add(duration)
    )
}

/// Removes from `value` every key the incoming `patch` set to `null` —
/// `set_action_end`'s delete rule (spec §6). Only keys the patch mentions
/// are touched, so a `null` that was already in the end patch (animating a
/// shadow away, say) survives untouched. `shift_remove`, because under
/// `preserve_order` `Map::remove` swaps the last key into the hole.
fn prune_removed(value: &mut Value, patch: &Value, depth: u32) {
    let Value::Object(patched) = patch else {
        return;
    };
    let Value::Object(target) = value else {
        return;
    };
    if depth >= MAX_PATCH_DEPTH {
        return;
    }
    for (key, sub) in patched {
        if sub.is_null() {
            target.shift_remove(key);
        } else if let Some(slot) = target.get_mut(key) {
            prune_removed(slot, sub, depth + 1);
        }
    }

//! The two background commands — spec §6's `add_background` and
//! `add_blurred_background` (road map 2, phase 6c).
//!
//! Both answer one question: what goes BEHIND the picture. A 16:10 screen
//! recording on a 16:9 timeline, a phone capture on a landscape canvas, a
//! title standing on nothing — each leaves the canvas showing through, and
//! an editor fills it two ways. A **plate**: a colour, or an image, sized
//! to the canvas. Or a **blurred copy of the clip itself**, blown up past
//! the frame, which is the screencast look — the backdrop is always the
//! right colour because it is made of the same pixels.
//!
//! Both put exactly ONE clip on a NEW track inserted at index 0, the
//! back-most. Not on the back-most EXISTING track: a background is behind
//! everything, and a fresh track is the only place that is true whatever
//! the stack already holds — no overlap to check, nothing already there to
//! push aside, and one undo step to take it all away again. The plate
//! starts at 0 and runs the timeline's length; the blurred copy starts and
//! ends exactly where the clip it copies does.
//!
//! # Why these are core ops
//!
//! The plan of record called Add Blurred Background "a composite over
//! existing ops", and it is worth writing down why it is not, because the
//! recipe it proposed cannot be built and the one that replaces it carries
//! a constraint no single op states.
//!
//! The proposed recipe was the clip's clipboard payload `paste`d onto a new
//! track; that payload carries no `nests` key. (This op refuses a nest clip
//! too, for its own reason — see [`Project::add_blurred_background`] — so
//! that half of the argument is spent and is written down spent rather than
//! left standing.) Re-placing the media with `add_clip`
//! instead loses the SOURCE WINDOW — `add_clip` gives the whole media — so
//! the backdrop of a trimmed clip shows different frames from the
//! foreground and drifts out of sync, which is the one thing this feature
//! may not do; repairing it means a `trim_start` and a `trim_end` in the
//! app over arithmetic this crate already owns. `duplicate` is no way out
//! either: it lands its copy one selection span LATER on the SAME track,
//! where it can collide with a neighbour, be refused, or silently acquire a
//! cross dissolve for a reason the user never asked about.
//!
//! Here it is `clip.clone()` with five fields changed, and the derived
//! values — the source's pixel size, [`Project::fill_scale`], and the
//! [`crate::props_check::SCALE_MAX`] clamp on it — are core vocabulary the
//! app does not have. `insert_clip`, `overwrite_clip` and `add_zoom_action`
//! are the standing precedent and they name the rule: **a composite becomes
//! an op when composing it out of existing ops carries a constraint that no
//! single half states.** Frame-exact sync with the source clip is exactly
//! such a constraint.
//!
//! # What a blurred copy does NOT keep
//!
//! Five things, and each is a wrong picture — or a wrong SOUND — if it is
//! carried:
//!
//! 1. **Its audio.** The copy has the same media, the same in point and the
//!    same span, so a mix that played both would play one source twice:
//!    roughly +6 dB and comb filtering on every blurred background, and
//!    wrong numbers out of `detect_silence` and the level meter besides.
//!    It is INVISIBLE in a still frame, which is the reason it is stated
//!    here and tested by name rather than left to a render to catch. The
//!    switch moves: the copy's `enabled` is `{video: true, audio: false}`,
//!    which is exactly the pair `detach_audio` sets, read the other way
//!    round. Its `enabled.video` is forced ON for the same reason its audio
//!    is forced off: the copy exists to draw, so a hidden foreground clip
//!    must not mint a hidden backdrop that looks like the command did
//!    nothing.
//! 2. **Its duck** — and ONLY its duck, out of the whole audio group. A
//!    volume, a fade, a pan are facts about this clip's own sound and are
//!    inert once nothing plays it, so they travel; a duck is not about this
//!    clip's sound at all, it is an instruction to lower everything ELSE.
//!    [`Project::duckers`] collects every clip carrying one with no test of
//!    `enabled.audio`, of a mute, or of a solo — a duck is a fact about the
//!    timeline, gathered before any voice is assigned — so a copy that kept
//!    it would be a ducker on no track, ducking the whole mix INCLUDING the
//!    clip it was copied from, which the `others` filter cannot exclude
//!    because the copy is a voice nowhere. A picture command would halve
//!    the level of the very clip it is standing behind, and no rendered
//!    frame could see it. Clearing it on the copy is the narrow fix and the
//!    one this op is entitled to make. The wide one — teaching `duckers`
//!    that a clip nobody can hear does not duck — would also change how
//!    `detach_audio` has sounded since M2, which is a shipped feature and
//!    its own change to measure.
//! 3. **Its transition.** A `transition_in` describes an overlap on the
//!    ORIGINAL track (`detach_audio`'s stated reason). The copy is alone on
//!    a new track, so it has no predecessor and nothing to dissolve from.
//! 4. **Its actions.** A zoom action on the foreground would otherwise
//!    animate the backdrop out from under it — the background sliding while
//!    the picture on top of it moves, which is the opposite of what a
//!    background is for.
//! 5. **Its name and label.** The copy is named "Blurred Background", so
//!    the timeline can tell the two apart at a glance, and its label is
//!    cleared: a label is a mark the user put on one clip, and copying it
//!    would file the backdrop under a category nobody chose for it.
//!
//! Everything else IS kept, deliberately: the source and its in point (the
//! sync), the speed, the rest of the audio group, and every video property
//! the copy does not overwrite — opacity, rotation, corner radius, the
//! colour controls, the shadow, the reflection, the spotlight and the
//! hidden regions. Two honest limits fall out of that. A ROTATED clip gives a
//! rotated backdrop, and the fill scale is measured square, so a large
//! rotation can leave the corners showing; measuring through the rotation
//! the way `edit_zoom.rs` does would make the common case (no rotation)
//! magnify for a corner that is not there. And a hidden REGION rides along
//! at the copy's own scale against an uncropped rect, so it no longer
//! covers what it covered on the original — which costs nothing in
//! practice, because a full-strength blur over the whole layer is already
//! hiding everything the region was hiding.
//!
//! # The derived values
//!
//! - **`scale`** is [`Project::fill_scale`] of the source's pixel size:
//!   `max(cw/sw, ch/sh)`, clamped to the layer bounds. FILL, not fit — a
//!   backdrop that leaves a bar down the side has failed at its one job.
//! - **`x`, `y`** are 0. Fill leaves the surplus outside the canvas on one
//!   axis, and the only placement that spends it evenly is the centre.
//! - **`crop`** is cleared. A crop is what the editor cut away from the
//!   foreground; the backdrop is the thing that fills what the crop left
//!   empty, so keeping it would take the same bite out of both.
//! - **`filters`** becomes exactly one full-strength blur, REPLACING the
//!   clip's own stack rather than appending to it. The blur is what makes

//! `add_zoom_action` — the screencast zoom, and the placement equation
//! behind it (spec §5.3, spec §6).
//!
//! A screencast zoom is not a new kind of animation: it is an ordinary
//! [`crate::model::Action`] whose end patch holds three numbers — `scale`,
//! `x` and `y` — chosen so that a rectangle the user drew on the picture
//! ends up filling the canvas. The op exists because CHOOSING those three
//! numbers is arithmetic nobody should do twice. The canvas gesture, the
//! inspector's button and the MCP tool all want the same answer, and the
//! road map's premise for this phase is that the answer lives in the core,
//! where spec §5.3's placement rule already lives, rather than being
//! re-derived in a drag handler.
//!
//! It is a module of its own rather than a fifth function in
//! `edit_action.rs` because its substance is GEOMETRY, not action
//! bookkeeping: `edit_action.rs` owns one rule (actions on a clip may not
//! overlap) and this file owns one equation. Phase 3c's "Place on Canvas"
//! and any later "zoom to selection" cite the derivation below rather than
//! repeating it.
//!
//! # The frames
//!
//! Two coordinate spaces meet here, and confusing them is the whole risk.
//!
//! - **Q, the spotlight's frame.** Source pixels measured from the CENTRE
//!   of the layer's cropped rect, y down. [`crate::model::Spotlight`] and
//!   (from format version 4) [`crate::model::ObscureRegion`] are in it, and
//!   so is [`ZoomRegion`]: `x`/`y` are the region's CENTRE, not a corner,
//!   and `width`/`height` its size. The field names do not say "centre",
//!   which is why the op table row, the doc comment on [`ZoomRegion`] and
//!   the MCP tool description all say it out loud. A length in Q costs
//!   nothing to convert because the layer's own `scale` is what turns it
//!   into canvas pixels.
//! - **C, canvas pixels**, from the canvas's top-left, y down. `video.x`
//!   and `video.y` are the ONLY per-layer lengths in it, and they are an
//!   offset of the layer's centre from the CANVAS centre.
//!
//! # The placement rule (★)
//!
//! With `W`, `H` the canvas size, `l, t, r, b` the crop insets in source
//! pixels, `s` the layer's `scale`, `θ` its `rotation` in degrees and
//! `R(θ)` the clockwise-on-a-y-down-screen rotation ([`crate::nest`]'s
//! `rotate`, which is the same sign as `Compositor.metal`'s `rotate2`):
//!
//! ```text
//! anchor = (W/2 + video.x, H/2 + video.y)   the centre of the UNCROPPED
//!                                           rect, and the rotation pivot
//! c      = ((l − r)/2, (t − b)/2)           the cropped rect's centre,
//!                                           in source px, relative to it
//!
//! canvas(q) = anchor + s · R(θ) · (c + q)                            (★)
//! ```
//!
//! (★) is the one placement rule the whole editor draws by. The Metal
//! vertex stage, `ProjectSnapshot.canvasRect` on the Swift side and
//! [`crate::nest::Frame::place`] are three implementations of it; `c` is
//! literally the expression `Frame::enter` uses to fold a nest's crop.
//!
//! # Solving it for a region
//!
//! Given a region whose centre is `q_c = (rx, ry)` and whose size is
//! `rw × rh`, find the `s′`, `x′`, `y′` that put it on the canvas.
//!
//! **The position.** Require the region's centre to land at the canvas
//! centre and substitute into (★):
//!
//! ```text
//! (W/2 + x′, H/2 + y′) + s′ · R(θ) · (c + q_c) = (W/2, H/2)
//!         ⟹  (x′, y′) = − s′ · R(θ) · (c + q_c)
//! ```
//!
//! So the offsets depend on the scale, which is why the scale is resolved —
//! and clamped — FIRST.
//!
//! **The scale, measured through the rotation.** Once placed, the region is
//! a rotated `s′·rw × s′·rh` rectangle centred on the canvas centre, and
//! the canvas is a `W × H` rectangle centred on the same point. A rectangle
//! contains a rotated rectangle exactly when it contains its four corners,
//! so comparing axis extents is not an approximation here — it is necessary
//! AND sufficient. With `k = |cos θ|` and `m = |sin θ|` the region's
//! canvas-space bounding box is `s′(rw·k + rh·m) × s′(rw·m + rh·k)`, and
//! the canvas's bounding box measured in the LAYER's axes is
//! `(W·k + H·m) × (W·m + H·k)` canvas pixels:
//!
//! ```text
//! fit  (the whole region visible):  s′ = min( W / (rw·k + rh·m),
//!                                             H / (rw·m + rh·k) )
//! fill (the region covers the canvas): s′ = max( (W·k + H·m) / rw,
//!                                                (W·m + H·k) / rh )
//! ```
//!
//! Both collapse to the naïve `min`/`max(W/rw, H/rh)` at θ = 0, so the
//! unrotated case — which is every screencast — reads exactly as it would
//! have without the rotation terms, and a rotated clip stops hanging its
//! corners off the canvas. The denominators cannot vanish: `rw` and `rh`
//! are checked positive and `k² + m² = 1`, so `rw·k + rh·m ≥ min(rw, rh)`.
//!
//! **Worked example, the one the tests pin.** Canvas 1920×1080, no crop,
//! θ = 0, region 480×270 centred at `(480, 0)`. Then
//! `s′ = min(1920/480, 1080/270) = 4` and `(x′, y′) = −4·(480, 0) =
//! (−1920, 0)`. Check it against (★): `anchor′ = (960 − 1920, 540)`, so the
//! region's centre lands at `(−960 + 4·480, 540) = (960, 540)`, the canvas
//! centre, and its width is `480·4 = 1920`, the canvas width. Turn the same
//! clip 90° and `s′` becomes `min(1920/270, 1080/480) = 2.25`: the two
//! formulas genuinely differ under rotation, which is the point of carrying
//! `k` and `m`.
//!
//! # What it reads, and what it writes
//!
//! Rotation and crop come from the clip EVALUATED at clip time `at`
//! ([`crate::model::Project::evaluate_clip`]), not from its base props.
//! That is the state the frame the user drew on was rendered in, and it is
//! the reading that survives an earlier action having already rotated or
//! cropped the layer — the common case on a screencast with two zooms in a
//! row. Evaluating before the new action is inserted is not circular: the
//! action does not exist yet, and at `clip_t == at` it would contribute
//! nothing anyway (its progress there is 0).
//!
//! The end patch is `{"video": {"scale", "x", "y"}}` and nothing else. No
//! rotation, no crop, no source size: `sw` and `sh` cancel out of `c`
//! entirely, so the op needs no source measurement — which is what lets it
//! zoom a TEXT clip, whose source size only the renderer can know
//! (`Project::source_size` answers `None` for one).
//!
//! Values go out raw. The core rounds no property anywhere; `canvasRound`
//! on the Swift side is a gesture-side nicety so a drag does not write
//! seventeen digits, and a computed op is not a drag.
//!
//! # The clamp, and the two limits worth knowing
//!
//! An action's end patch is deliberately NOT range-checked
//! (`edit_action.rs`), so this op is its own last line of defence. If the
//! required `s′` exceeds [`SCALE_MAX`] it is clamped and `x′`/`y′` are
