    menu.addItem(
        item("Export Captions…", #selector(EditorViewController.exportCaptions(_:))))
    menu.addItem(
        item("Consolidate Media…", #selector(EditorViewController.consolidateMedia(_:))))
    // Road map 10's G5b: a face or a picture into the package's
